{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg1:#0f1724;--glass:rgba(255,255,255,0.06);--glass-2:rgba(255,255,255,0.03);--accent:#7ee7c7;--muted:#bcdad7;--card:#0b1220}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6f0ef;background:linear-gradient(180deg,var(--bg1),#031020);-webkit-font-smoothing:antialiased}
    /* scaffold */
    .wrap{max-width:1100px;margin:40px auto;padding:28px;position:relative}
    header{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}
    .brand{display:flex;align-items:center;gap:14px}
    .logo{width:56px;height:56px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(135deg,var(--glass),var(--glass-2));box-shadow:0 6px 18px rgba(0,0,0,0.6);backdrop-filter: blur(6px);border:1px solid rgba(255,255,255,0.04)}
    .brand h1{font-size:16px;margin:0;color:#fff}
    .brand p{margin:0;font-size:12px;color:var(--muted)}
    nav a{color:var(--muted);text-decoration:none;margin-left:16px;font-size:14px}

    /* hero */
    .hero{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:14px;padding:22px;display:flex;gap:18px;align-items:center;backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,0.04)}
    .hero-left{flex:1}
    .hero h2{margin:0 0 6px 0;color:#fff;font-size:20px}
    .hero p{margin:0;color:var(--muted)}

    /* comparator */
    .comparator{margin-top:18px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03);display:grid;grid-template-columns:1fr 220px;gap:12px}
    .toggle{display:flex;align-items:center;justify-content:flex-end;gap:8px}
    .toggle button{background:transparent;border:1px solid rgba(255,255,255,0.06);padding:8px 12px;border-radius:999px;color:var(--muted);cursor:pointer}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),#9af3dd);color:#052018;border:none}

    .plans{display:flex;gap:12px}
    .plan{flex:1;padding:14px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.04)}
    .plan h3{margin:0 0 6px 0;color:#fff;font-size:16px}
    .price{font-size:28px;color:var(--accent);margin:6px 0;min-height:38px;display:flex;align-items:flex-end;gap:8px}
    .price small{font-size:12px;color:var(--muted)}
    .features{color:var(--muted);font-size:13px;margin-top:8px}
    .cta-row{display:flex;gap:10px;margin-top:12px}
    .btn{padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#9af3dd);border:none;color:#052018;cursor:pointer}
    .ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted)}

    /* small note */
    .note{margin-top:12px;font-size:12px;color:var(--muted)}

    /* animated number */
    .num{font-variant-numeric:tabular-nums}

    /* footer */
    footer{margin-top:26px;color:var(--muted);font-size:13px;display:flex;justify-content:space-between}

    /* subtle SVG pattern */
    .pattern{position:fixed;right:-120px;top:-80px;opacity:0.07;transform:rotate(12deg);pointer-events:none}

    /* responsive */
    @media (max-width:880px){.wrap{margin:18px;padding:18px}.comparator{grid-template-columns:1fr}.plans{flex-direction:column}}
  </style>
</head>
<body>
  <svg class="pattern" width="420" height="420" viewBox="0 0 420 420" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden>
    <defs>
      <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#7ee7c7"/><stop offset="1" stop-color="#8bdcf0"/></linearGradient>
      <pattern id="p1" patternUnits="userSpaceOnUse" width="80" height="80" patternTransform="rotate(25)">
        <rect width="80" height="80" fill="transparent"/>
        <circle cx="10" cy="10" r="2.6" fill="#9fe8d0" fill-opacity="0.6"/>
        <circle cx="50" cy="50" r="2.6" fill="#7ee7c7" fill-opacity="0.5"/>
        <rect x="20" y="20" width="8" height="8" rx="2" fill="#8bdcf0" fill-opacity="0.08"/>
      </pattern>
    </defs>
    <rect width="420" height="420" fill="url(#p1)"/>
    <circle cx="60" cy="360" r="160" fill="url(#g1)" fill-opacity="0.06"/>
  </svg>

  <div class="wrap">
    <header>
      <div class="brand">
        <div class="logo" aria-hidden>
          <svg width="34" height="34" viewBox="0 0 34 34" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="1" y="1" width="32" height="32" rx="7" fill="url(#lg)" stroke="rgba(255,255,255,0.06)"/></svg>
        </div>
        <div>
          <h1>{{BUSINESS_NAME}}</h1>
          <p>{{TAGLINE}}</p>
        </div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="services.html">Offerings</a>
        <a href="conditions.html">Comforts</a>
        <a href="approach.html">Practice</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">Our Story</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Say Hi</a>
      </nav>
    </header>

    <section class="hero">
      <div class="hero-left">
        <h2>Thoughtful pricing for steady-care and group learning</h2>
        <p>Choose how you invest in your rhythms: short monthly support or concentrated packages that lean into momentum. No promises of cures — just clear options and educational guidance.</p>
      </div>
      <div style="text-align:right">
        <div style="font-size:12px;color:var(--muted)">Questions?</div>
        <div style="font-weight:700;color:#fff">{{PHONE}}</div>
        <div style="font-size:12px;color:var(--muted)">{{EMAIL}}</div>
      </div>
    </section>

    <div class="comparator" aria-live="polite">
      <div>
        <div style="display:flex;align-items:center;justify-content:space-between">
          <strong style="color:#fff">Compare plans</strong>
          <div class="toggle" role="tablist" aria-label="Pricing toggle">
            <button id="btn-monthly" class="active" aria-pressed="true">Monthly</button>
            <button id="btn-package" aria-pressed="false">Package</button>
          </div>
        </div>

        <div class="plans" style="margin-top:12px">
          <div class="plan" data-plan="sprout">
            <h3>Sprout Support</h3>
            <div class="price"><span class="num" data-month="89" data-package="380">$<span class="val">89</span></span><small>/mo or one-off</small></div>
            <div class="features">Intro guidance, biweekly check-ins, care roadmap.</div>
            <div class="cta-row">
              <button class="btn" data-plan-action>Choose</button>
              <button class="ghost">Learn more</button>
            </div>
          </div>

          <div class="plan" data-plan="renew">
            <h3>Root Renewal</h3>
            <div class="price"><span class="num" data-month="179" data-package="780">$<span class="val">179</span></span><small>/mo or package</small></div>
            <div class="features">Monthly coaching, symptom toolkit, community check-ins.</div>
            <div class="cta-row">
              <button class="btn" data-plan-action>Choose</button>
              <button class="ghost">Learn more</button>
            </div>
          </div>

          <div class="plan" data-plan="compass">
            <h3>Cohort Compass</h3>
            <div class="price"><span class="num" data-month="129" data-package="990">$<span class="val">129</span></span><small>/mo or cohort</small></div>
            <div class="features">Group cohort, structured modules, peer labs, 3-month cycles.</div>
            <div class="cta-row">
              <button class="btn" data-plan-action>Join Cohort</button>
              <button class="ghost">See schedule</button>
            </div>
          </div>
        </div>

        <div class="note">Monthly plans are billed month-to-month. Package amounts reflect a single payment option for the term described. All plans include educational materials and suggested self-care — not guaranteed outcomes.</div>
      </div>

      <aside style="padding-left:12px;border-left:1px dashed rgba(255,255,255,0.03)">
        <strong style="color:#fff">Quick calculator</strong>
        <p style="color:var(--muted);margin:8px 0 12px 0">Toggle between monthly and package to see totals animate. Use this to choose what fits your budget and commitment rhythm.</p>
        <div style="display:grid;gap:10px">
          <label style="font-size:13px;color:var(--muted)">Estimated start month
            <select id="start-month" style="width:100%;margin-top:6px;padding:8px;border-radius:8px;background:transparent;border:1px solid rgba(255,255,255,0.04);color:#fff">
              <option>Next month</option>
              <option>Two months</option>
              <option>When cohort opens</option>
            </select>
          </label>

          <div style="background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.03)">
            <div style="font-size:12px;color:var(--muted)">Selected plan</div>
            <div id="calc-plan" style="font-weight:700;color:#fff;margin-top:6px">Root Renewal</div>
            <div style="margin-top:6px;color:var(--muted)">Total: <span id="calc-total" style="font-weight:700;color:var(--accent)">$780</span></div>
          </div>

          <button class="btn" onclick="location.href='{{PRIMARY_CTA_URL}}'">{{PRIMARY_CTA_LABEL}}</button>
        </div>
      </aside>
    </div>

    <footer>
      <div>Serving {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}" style="color:var(--muted);text-decoration:none">{{EMAIL}}</a></div>
      <div style="color:var(--muted)">Need invoice details? Call {{PHONE}}</div>
    </footer>
  </div>

  <script>
    // Pricing comparator toggle + animated numbers
    const btnMonthly = document.getElementById('btn-monthly');
    const btnPackage = document.getElementById('btn-package');
    const nums = document.querySelectorAll('.num');
    const calcPlan = document.getElementById('calc-plan');
    const calcTotal = document.getElementById('calc-total');
    let activeMode = 'month';

    function animateNumber(el, from, to, duration=600){
      const start = performance.now();
      const vFrom = Number(from);
      const vTo = Number(to);
      requestAnimationFrame(function step(ts){
        const t = Math.min(1,(ts-start)/duration);
        const eased = 1 - Math.pow(1-t,3);
        const current = Math.round(vFrom + (vTo-vFrom)*eased);
        el.textContent = current;
        if(t<1) requestAnimationFrame(step);
      });
    }

    function setMode(mode){
      activeMode = mode;
      btnMonthly.classList.toggle('active', mode==='month');
      btnPackage.classList.toggle('active', mode==='package');
      btnMonthly.setAttribute('aria-pressed', mode==='month');
      btnPackage.setAttribute('aria-pressed', mode==='package');

      // animate each number
      nums.forEach(n =>{
        const valEl = n.querySelector('.val') || n.querySelector('span');
        const from = Number(valEl.textContent);
        const to = Number(mode==='month' ? n.dataset.month : n.dataset.package);
        animateNumber(valEl, from, to);
      });

      // update small calculator total: pick second plan for demo
      const selector = document.querySelector('.plan[data-plan="renew"] .num');
      const total = mode==='month' ? selector.dataset.month : selector.dataset.package;
      calcPlan.textContent = 'Root Renewal';
      animateNumber(calcTotal, Number(calcTotal.textContent.replace(/[^0-9]/g,''))||0, total);
    }

    btnMonthly.addEventListener('click',()=>setMode('month'));
    btnPackage.addEventListener('click',()=>setMode('package'));

    // initial
    document.addEventListener('DOMContentLoaded',()=>{
      // set displayed starting numbers from data-month
      nums.forEach(n=>{ const val = n.dataset.month; n.querySelector('.val').textContent = val; });
      calcTotal.textContent = '$' + document.querySelector('.plan[data-plan="renew"] .num').dataset.package;
    });

    // plan buttons wire-up
    document.querySelectorAll('[data-plan-action]').forEach(btn=>btn.addEventListener('click',e=>{
      const planEl = e.target.closest('.plan');
      const name = planEl.querySelector('h3').textContent;
      const amount = planEl.querySelector('.val').textContent;
      // friendly booking action
      alert('You selected "'+name+'" — '+(activeMode==='month' ? 'Monthly: $'+amount : 'Package: $'+amount)+".\nRedirecting to booking...");
      location.href='book.html';
    }));
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Our Story — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#05121a;--glass:rgba(255,255,255,0.04);--muted:#9fbdb7;--accent:#ffd6a5}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#02121a);color:#e9fbf6;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial}
    .site{max-width:1040px;margin:36px auto;padding:22px}
    header{display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:56px;height:56px;border-radius:12px;background:linear-gradient(135deg,rgba(255,255,255,0.02),transparent);display:grid;place-items:center;border:1px solid rgba(255,255,255,0.04)}
    nav a{color:var(--muted);text-decoration:none;margin-left:14px}

    .lead{margin-top:18px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:14px;border:1px solid rgba(255,255,255,0.04);backdrop-filter:blur(6px)}
    .lead h2{margin:0 0 6px 0}
    .lead p{margin:0;color:var(--muted)}

    /* Proof gallery */
    .gallery{display:grid;grid-template-columns:1fr 280px;gap:14px;margin-top:14px}
    .rotator{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.04)}
    .testimonial{min-height:120px;transition:opacity .45s ease,transform .45s ease;opacity:0;transform:translateY(8px)}
    .testimonial.active{opacity:1;transform:translateY(0)}
    .quote{font-size:15px;color:#fff;margin-bottom:10px}
    .who{font-size:13px;color:var(--muted)}

    .badges{padding:14px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);border:1px solid rgba(255,255,255,0.03)}
    .badge-grid{display:flex;flex-wrap:wrap;gap:10px}
    .badge{background:rgba(255,255,255,0.02);padding:8px 10px;border-radius:10px;border:1px solid rgba(255,255,255,0.03);font-size:13px;position:relative;cursor:default}
    .badge[data-tooltip]:hover::after{content:attr(data-tooltip);position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 10px);background:#021217;color:#bfeae0;padding:8px;border-radius:8px;white-space:nowrap;font-size:12px;box-shadow:0 8px 20px rgba(0,0,0,0.6)}

    .proof-controls{display:flex;gap:8px;margin-top:10px}
    .dot{width:10px;height:10px;border-radius:50%;background:rgba(255,255,255,0.06);cursor:pointer}
    .dot.active{background:var(--accent)}

    .about-grid{display:grid;grid-template-columns:1fr 320px;gap:14px;margin-top:14px}
    .card{padding:14px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);border:1px solid rgba(255,255,255,0.03)}

    footer{margin-top:18px;color:var(--muted);font-size:13px}

    @media (max-width:920px){.gallery,.about-grid{grid-template-columns:1fr}.badge-grid{justify-content:flex-start}}
  </style>
</head>
<body>
  <div class="site">
    <header>
      <div class="brand">
        <div class="logo" aria-hidden>
          <svg width="36" height="36" viewBox="0 0 36 36" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="2" y="2" width="32" height="32" rx="8" fill="#062b2a" stroke="rgba(255,255,255,0.03)"/></svg>
        </div>
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Welcome</a>
        <a href="services.html">Offerings</a>
        <a href="conditions.html">Comforts</a>
        <a href="approach.html">Practice</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">Our Story</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Say Hi</a>
      </nav>
    </header>

    <section class="lead">
      <h2>Who we are — a practical, curious approach</h2>
      <p>We blend practical lifestyle guidance with evidence-aware integrative tools. Our work is about clarity, pace, and learning together — no quick fixes, just thoughtful support.</p>
    </section>

    <section class="gallery" aria-label="Proof gallery">
      <div class="rotator">
        <div id="testimonials">
          <div class="testimonial active" data-index="0">
            <div class="quote">"I learned small, useful practices that fit into my week. The group met me where I was and moved gently forward."</div>
            <div class="who">— A cohort participant, {{CITY}}</div>
          </div>
          <div class="testimonial" data-index="1">
            <div class="quote">"Clear lessons and friendly coaching — I stopped feeling overwhelmed and started experimenting with realistic changes."</div>
            <div class="who">— Private client, {{STATE}}</div>
          </div>
          <div class="testimonial" data-index="2">
            <div class="quote">"The roadmap helped me track what mattered. It wasn’t dramatic overnight — it was better: steady."</div>
            <div class="who">— Workshop attendee</div>
          </div>
        </div>
        <div class="proof-controls" role="tablist" aria-label="Testimonial controls">
          <div class="dot active" data-index="0" tabindex="0"></div>
          <div class="dot" data-index="1" tabindex="0"></div>
          <div class="dot" data-index="2" tabindex="0"></div>
          <div style="margin-left:auto;color:var(--muted);font-size:13px">Verified notes</div>
        </div>
      </div>

      <aside class="badges" aria-hidden="false">
        <strong style="display:block;color:#fff;margin-bottom:8px">Credibility & partners</strong>
        <div class="badge-grid">
          <div class="badge" data-tooltip="Peer-reviewed collaboration in community health">Community Research Partner</div>
          <div class="badge" data-tooltip="Guest lecturer and workshop lead">University Workshop Series</div>
          <div class="badge" data-tooltip="Continuing education credits available for select modules">CE-eligible Modules</div>
          <div class="badge" data-tooltip="Presented case studies at national integrative conferences">Conference Speaker</div>
          <div class="badge" data-tooltip="Subject to professional licensing in clinical practice">Licensed Clinicians</div>
        </div>
        <p style="color:var(--muted);font-size:12px;margin-top:12px">Hover badges for notes. Testimonials rotate automatically — they are anonymized and used with consent for educational purposes.</p>
      </aside>
    </section>

    <section class="about-grid">
      <div class="card">
        <h3 style="margin-top:0">Our method</h3>
        <p style="color:var(--muted)">We weave habit micro-experiments, physiology-aware pacing, and community reflection. Each plan is educational: learn what works for you, and build repeatable practices into your days.</p>
        <ul style="color:var(--muted)">
          <li>Small experiments with measurable signals</li>
          <li>Rhythm-friendly scheduling — we adapt to life’s demands</li>
          <li>Clear checkpoints instead of vague goals</li>
        </ul>
      </div>

      <aside class="card">
        <h4 style="margin:0 0 8px 0">Meet the team</h4>
        <div style="color:var(--muted);font-size:13px">Our lead clinicians combine training in integrative medicine, behavior change coaching, and systems thinking. We aim to be transparent about evidence, respectful of preferences, and curious about context.</div>
        <div style="margin-top:12px"><button onclick="location.href='book.html'" style="padding:10px 12px;border-radius:10px;border:none;background:linear-gradient(90deg,var(--accent),#ffd6a5);color:#021017;cursor:pointer">Reserve an intro</button></div>
      </aside>
    </section>

    <footer>
      <p style="color:var(--muted)">We do not promise cures. Our materials are educational and supportive. For urgent medical issues contact emergency services or your licensed provider. Contact: {{EMAIL}} • {{PHONE}}</p>
    </footer>
  </div>

  <script>
    // Proof gallery rotation
    (function(){
      const items = document.querySelectorAll('.testimonial');
      const dots = document.querySelectorAll('.dot');
      let active = 0;
      let timer;
      function show(n){
        items.forEach(i=>i.classList.remove('active'));
        dots.forEach(d=>d.classList.remove('active'));
        items[n].classList.add('active');
        dots[n].classList.add('active');
        active = n;
      }
      function next(){ show((active+1)%items.length); }
      dots.forEach(d=>d.addEventListener('click',e=>{ clearInterval(timer); show(Number(d.dataset.index)); timer = setInterval(next,4500); }));
      dots.forEach(d=>d.addEventListener('keydown',e=>{ if(e.key==='Enter') { d.click(); } }));
      timer = setInterval(next,4500);
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071522;--panel:rgba(255,255,255,0.03);--muted:#bcdad7;--accent:#9fe8d0}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#021012);color:#eafffb;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial}
    .container{max-width:920px;margin:28px auto;padding:20px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;margin-left:12px}

    .grid{display:grid;grid-template-columns:1fr 360px;gap:16px;margin-top:16px}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.04)}
    label{display:block;margin-bottom:8px;font-size:13px;color:var(--muted)}
    input,select,textarea{width:100%;padding:10px;border-radius:10px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#eafffb}
    .small{font-size:13px;color:var(--muted)}
    .btn{margin-top:10px;padding:10px 12px;border-radius:10px;border:none;background:linear-gradient(90deg,var(--accent),#7ee7c7);color:#04201b;cursor:pointer}

    .sidebar .slot{padding:12px;border-radius:10px;background:rgba(255,255,255,0.01);border:1px solid rgba(255,255,255,0.03);margin-bottom:10px}
    .slot h4{margin:0 0 6px 0}
    .disclaimer{font-size:12px;color:var(--muted);margin-top:12px}

    @media (max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="container">
    <header>
      <div>
