          <label>Preferred time frame
            <select id="timeframe">
              <option>Next 2 weeks</option>
              <option>Next month</option>
              <option>When cohort opens</option>
            </select>
          </label>

          <label>Tell us briefly about your goals<textarea id="notes" rows="4" placeholder="Short note about what you're hoping for"></textarea></label>

          <div style="display:flex;gap:8px;align-items:center">
