  <script>
    // Local booking micro-interaction
    const form = document.getElementById('booking-form');
    const sendBtn = document.getElementById('send-btn');
    sendBtn.addEventListener('click',()=>{
      const name = document.getElementById('name').value.trim();
      const email = document.getElementById('email').value.trim();
      if(!name || !email){ alert('Please provide name and email.'); return; }
      sendBtn.disabled = true;
      sendBtn.textContent = 'Sending...';
      // simulate send
      setTimeout(()=>{
        alert('Thanks '+name+" — we've received your request. We'll follow up at "+email+" with next steps.");
        sendBtn.textContent = 'Request intro';
        sendBtn.disabled = false;
        form.reset();
        location.href = 'contact.html';
      },900);
    });
  </script>
